@layer base {
  html,
  body {
    margin: 0;
    padding: 0;
    width: 100%;
    height: 100%;
    background-color: #E9E1D3;
    font-family: var(--font-sans), system-ui, -apple-system, sans-serif;
  }
}

/* Custom archival range slider for the developer scrubber */
input[type="range"].archival-range {
  -webkit-appearance: none;
  appearance: none;
  background: transparent;
  cursor: pointer;
}

input[type="range"].archival-range::-webkit-slider-runnable-track {
  height: 3px;
  border-radius: 9999px;
  background: rgba(28, 25, 26, 0.18);
}

input[type="range"].archival-range::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 13px;
  height: 13px;
  margin-top: -5px;
  border-radius: 9999px;
  background: #722C3B;
  border: 2px solid #E9E1D3;
  box-shadow: 0 1px 3px rgba(28, 25, 26, 0.35);
  transition: transform 150ms cubic-bezier(0.16, 1, 0.3, 1);
}

input[type="range"].archival-range::-webkit-slider-thumb:hover {
  transform: scale(1.18);
}

input[type="range"].archival-range::-moz-range-track {
  height: 3px;
  border-radius: 9999px;
  background: rgba(28, 25, 26, 0.18);
}

input[type="range"].archival-range::-moz-range-thumb {
  width: 13px;
  height: 13px;
  border-radius: 9999px;
  background: #722C3B;
  border: 2px solid #E9E1D3;
  box-shadow: 0 1px 3px rgba(28, 25, 26, 0.35);
}

